import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'web-development';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [difficulty, setDifficulty] = useState(null);

  const fetchQuestions = async (level) => {
    setLoading(true);
    setDifficulty(level);
    try {
      const res = await fetch("http://localhost:5000/api/quiz/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ domain, difficulty: level })
      });
      setQuestions(await res.json());
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const cleanStr = (s) => s ? s.replace(/^[a-z0-9][\s).:-]+/i, "").trim().toLowerCase() : "";

  const score = questions.reduce((acc, q, idx) => {
    return acc + (cleanStr(selected[idx]) === cleanStr(q.answer) ? 1 : 0);
  }, 0);

  // 🔥 PERSONALIZED ROADMAP GENERATOR
  const handleFinalContinue = () => {
    const timeline = localStorage.getItem('timeline') || '4 weeks';
    const weeks = timeline.includes('month') ? parseInt(timeline) * 4 : parseInt(timeline);
    
    // Determine path intensity based on score
    let pathLabel = score >= 8 ? "Advanced" : score <= 4 ? "Foundational" : "Standard";

    // Simple grouping logic to fit your Roadmap.js 4-task-per-day UI
    const generatedPlan = Array.from({ length: weeks }, (_, wIdx) => {
      return Array.from({ length: 28 }, (_, tIdx) => 
        `${pathLabel} ${domain} - Week ${wIdx + 1}, Task ${tIdx + 1}`
      );
    });

    localStorage.setItem('roadmapPlan', JSON.stringify(generatedPlan));
    localStorage.setItem('quizScore', score);
    localStorage.setItem('totalQuestions', questions.length);
    navigate(`/roadmap/${domain}`);
  };

  if (!difficulty && !loading) return (
    <div className="max-w-md mx-auto mt-20 p-10 bg-white rounded-3xl border text-center">
      <h2 className="text-2xl font-bold mb-6">Choose Difficulty</h2>
      <div className="flex flex-col gap-4">
        {['Easy', 'Medium', 'Hard'].map(lvl => (
          <Button key={lvl} onClick={() => fetchQuestions(lvl.toLowerCase())}>{lvl}</Button>
        ))}
      </div>
    </div>
  );

  if (loading) return <div className="p-20 text-center">AI Generating Quiz...</div>;

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-3xl p-8 border shadow-sm">
        <h2 className="text-2xl font-bold capitalize mb-6">{domain.replace(/-/g, ' ')} ({difficulty})</h2>
        <div className="space-y-8">
          {questions.map((q, idx) => (
            <div key={idx} className="p-6 rounded-2xl bg-slate-50 border">
              <p className="font-semibold mb-4">{idx + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map(opt => (
                  <button
                    key={opt}
                    disabled={submitted}
                    onClick={() => setSelected(prev => ({ ...prev, [idx]: opt }))}
                    className={`p-4 text-left border rounded-xl transition ${selected[idx] === opt ? 'bg-blue-600 text-white' : 'bg-white'} 
                    ${submitted && cleanStr(opt) === cleanStr(q.answer) ? 'ring-4 ring-green-400' : ''}`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
        <div className="mt-8 border-t pt-6">
          {!submitted ? (
            <Button onClick={() => setSubmitted(true)} disabled={Object.keys(selected).length < questions.length}>Submit Quiz</Button>
          ) : (
            <div className="flex justify-between items-center">
              <span className="text-xl font-bold">Score: {score}/10</span>
              <Button onClick={handleFinalContinue}>Generate Roadmap →</Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
